import re
from datetime import datetime

OPER = re.compile(r"INFO avvio, operatore=(?P<nome>\w+)")
MIS = re.compile(r"MIS provino=(?P<p>\w+) Fmax=(?P<F>[\d.,]+)kN A=(?P<A>[\d.,]+)mm2")
ERR = re.compile(r"ERR provino=(?P<p>\w+) ")


def _num(s):
    return float(s.replace(",", "."))


def analizza(testo):
    out = {"operatore": None, "Rm": {}, "errori": [], "durata_min": 0}
    istanti = []
    for riga in testo.splitlines():
        if not riga.strip():
            continue
        istanti.append(datetime.strptime(riga[:19], "%Y-%m-%d %H:%M:%S"))
        if m := OPER.search(riga):
            out["operatore"] = m["nome"]
        elif m := MIS.search(riga):
            out["Rm"][m["p"]] = round(_num(m["F"]) * 1000 / _num(m["A"]), 1)
        elif m := ERR.search(riga):
            out["errori"].append(m["p"])
    if istanti:
        out["durata_min"] = int((istanti[-1] - istanti[0]).total_seconds() // 60)
    return out
